<script setup lang="ts">
import { Search, ArrowUpRight, ChevronDown, ChevronRight, RefreshCw, Swords, LayoutDashboard, Users, Gem, Radio, BookOpen, X, SlidersHorizontal, ExternalLink, Trophy, Activity, Target, Eye, Crosshair, Menu, Download } from 'lucide-vue-next'
import { demoProfile, demoMatches } from '#shared/demo'
const tab=ref('overview'), query=ref(''),region=ref('euw1'),busy=ref(false),error=ref(''),demo=ref(true),profile=ref<any>(demoProfile),matches=ref<any[]>(demoMatches),queue=ref('all'),expanded=ref(''),next=ref(0),hasMore=ref(false),mobile=ref(false)
const catalogQuery=ref(''),role=ref('all'),selected=ref<any>(null),detail=ref<any>(null),detailBusy=ref(false),detailError=ref(''),extra=ref<any>(null),extraBusy=ref(false),extraError=ref(''),timeline=ref<any>(null)
const {data:version}=await useFetch<any>('/api/catalog?kind=version')
const {data:champData}=await useFetch<any>('/api/catalog?kind=champion')
const {data:itemData}=await useFetch<any>('/api/catalog?kind=item')
const {data:spellData}=await useFetch<any>('/api/catalog?kind=summoner')
const {data:runeData}=await useFetch<any>('/api/catalog?kind=runes')
const {data:config}=await useFetch<any>('/api/config')
const patch=computed(()=>version.value?.version||'16.19.1'),cdn=computed(()=>`https://ddragon.leagueoflegends.com/cdn/${patch.value}/img`)
const champions=computed<any[]>(()=>Object.values(champData.value?.data||{})),items=computed<any[]>(()=>Object.entries(itemData.value?.data||{}).map(([id,data]:any)=>({id,...data})))
const filteredChampions=computed(()=>champions.value.filter(c=>(role.value==='all'||c.tags.includes(role.value))&&(c.name+' '+c.title).toLowerCase().includes(catalogQuery.value.toLowerCase())))
const filteredItems=computed(()=>items.value.filter(i=>i.maps?.['11']&&i.gold?.purchasable&&i.name.toLowerCase().includes(catalogQuery.value.toLowerCase())&&(role.value==='all'||i.tags.includes(role.value))))
const nav=[{id:'overview',label:'Panoramica',icon:LayoutDashboard},{id:'champions',label:'Campioni',icon:Users},{id:'items',label:'Oggetti',icon:Gem},{id:'live',label:'In partita',icon:Radio},{id:'sources',label:'Dati & API',icon:BookOpen}]
const rows=computed(()=>matches.value.filter(m=>queue.value==='all'||m.info.queueId===Number(queue.value)).map(m=>({...m,me:m.info.participants.find((p:any)=>p.puuid===profile.value.account.puuid)})).filter(m=>m.me))
const stats=computed(()=>{const r=rows.value,n=r.length||1,sum=(key:string)=>r.reduce((s,m)=>s+(m.me[key]||0),0);return{count:r.length,wins:r.filter(m=>m.me.win).length,wr:Math.round(r.filter(m=>m.me.win).length/n*100),kda:((sum('kills')+sum('assists'))/Math.max(1,sum('deaths'))).toFixed(2),cs:(r.reduce((s,m)=>s+(m.me.totalMinionsKilled+m.me.neutralMinionsKilled)/(m.info.gameDuration/60),0)/n).toFixed(1),vision:Math.round(sum('visionScore')/n),damage:Math.round(sum('totalDamageDealtToChampions')/n),kills:(sum('kills')/n).toFixed(1),deaths:(sum('deaths')/n).toFixed(1),assists:(sum('assists')/n).toFixed(1)}})
const championStats=computed(()=>{const map:Record<string,any>={};rows.value.forEach(m=>{const c=map[m.me.championName]||={name:m.me.championName,n:0,w:0,k:0,d:0,a:0};c.n++;c.w+=Number(m.me.win);c.k+=m.me.kills;c.d+=m.me.deaths;c.a+=m.me.assists});return Object.values(map).sort((a,b)=>b.n-a.n)})
const rank=computed(()=>profile.value?.ranked?.find((r:any)=>r.queueType==='RANKED_SOLO_5x5'))
const champion=(id:number)=>champions.value.find(c=>Number(c.key)===id)
const itemName=(id:number)=>itemData.value?.data?.[id]?.name||`Oggetto ${id}`
const spell=(id:number):any=>Object.values(spellData.value?.data||{}).find((s:any)=>Number(s.key)===id)
const rune=(id:number):any=>runeData.value?.flatMap((s:any)=>s.slots.flatMap((a:any)=>a.runes)).find((r:any)=>r.id===id)
const strip=(s:string)=>s?.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim()||''
const fmt=(n:number)=>new Intl.NumberFormat('it-IT',{notation:n>9999?'compact':'standard',maximumFractionDigits:1}).format(n||0)
const duration=(s:number)=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`
const queueName=(id:number)=>(({420:'Ranked Solo/Duo',440:'Ranked Flex',450:'ARAM',400:'Normale Draft',490:'Partita veloce',1700:'Arena'} as Record<number,string>)[id]||`Coda ${id}`)
function go(id:string){tab.value=id;catalogQuery.value='';role.value='all';mobile.value=false;extra.value=null;extraError.value=''}
function refreshProfile(){query.value=profile.value.account.gameName+'#'+profile.value.account.tagLine;region.value=profile.value.region;search()}
function resetDemo(){profile.value=demoProfile;matches.value=demoMatches;demo.value=true;error.value='';queue.value='all';hasMore.value=false;expanded.value='';go('overview')}
async function search(){const index=query.value.lastIndexOf('#');if(index<1||!query.value.slice(index+1).trim()){error.value='Inserisci il Riot ID completo, per esempio Nome#EUW.';return}busy.value=true;error.value='';try{const p=await $fetch<any>('/api/profile',{query:{name:query.value.slice(0,index),tag:query.value.slice(index+1),region:region.value}});profile.value=p;demo.value=false;matches.value=[];next.value=0;hasMore.value=false;expanded.value='';queue.value='all';go('overview');await loadMatches()}catch(e:any){error.value=e.data?.statusMessage||'Impossibile caricare il profilo.'}finally{busy.value=false}}
async function loadMatches(){busy.value=true;try{const r=await $fetch<any>('/api/matches',{query:{puuid:profile.value.account.puuid,region:profile.value.region,start:next.value}});matches.value=[...matches.value,...r.matches];next.value=r.next;hasMore.value=r.hasMore;if(r.failed)error.value=`${r.failed} partite non disponibili. Le statistiche usano solo quelle caricate.`}catch(e:any){error.value=e.data?.statusMessage||'Storico non disponibile.'}finally{busy.value=false}}
async function openChampion(c:any){selected.value={...c,kind:'champion'};detail.value=null;detailError.value='';detailBusy.value=true;try{const d=await $fetch<any>('/api/champion',{query:{id:c.id,version:patch.value}});detail.value=d.data[c.id]}catch{detailError.value='Dettagli non disponibili. Riprova più tardi.'}finally{detailBusy.value=false}}
async function loadExtra(kind:string){extraBusy.value=true;extraError.value='';extra.value=null;if(demo.value&&['live','challenges'].includes(kind)){extraError.value='Cerca un giocatore reale per consultare questi dati.';extraBusy.value=false;return}try{extra.value={kind,data:await $fetch('/api/extra',{query:{kind,region:profile.value.region,puuid:profile.value.account.puuid}})}}catch(e:any){extraError.value=e.data?.statusMessage||'Dati non disponibili.'}finally{extraBusy.value=false}}
async function loadTimeline(id:string){timeline.value=null;detailError.value='';selected.value={kind:'timeline',name:'Timeline della partita'};if(demo.value){detailError.value='La timeline è disponibile per le partite reali dopo aver configurato la chiave Riot.';return}detailBusy.value=true;try{timeline.value=await $fetch('/api/extra',{query:{kind:'timeline',region:profile.value.region,match:id}})}catch(e:any){detailError.value=e.data?.statusMessage||'Timeline non disponibile'}finally{detailBusy.value=false}}
function exportData(){const blob=new Blob([JSON.stringify({demo:demo.value,profile:profile.value,matches:matches.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rift-recap.json';a.click();URL.revokeObjectURL(url)}
function closeModal(e:KeyboardEvent){if(e.key==='Escape')selected.value=null}onMounted(()=>window.addEventListener('keydown',closeModal));onUnmounted(()=>window.removeEventListener('keydown',closeModal))
</script>

<template>
<div class="app-shell">
<aside :class="['sidebar',{open:mobile}]">
<a class="brand" href="#" @click.prevent="go('overview')"><span class="brand-mark">R</span><span>rift<span class="brand-light">recap</span><small>LEAGUE OF LEGENDS</small></span></a>
<div class="nav-title">IL TUO GIOCO, IN PROSPETTIVA</div>
<nav><button v-for="n in nav" :key="n.id" :class="{active:tab===n.id}" @click="go(n.id)"><component :is="n.icon" :size="19"/>{{n.label}}<span v-if="n.id==='live'" class="live-dot"/></button></nav>
<div class="sidebar-bottom"><div class="patch-label"><span/> DATA DRAGON {{patch}}</div><p>Dati di gioco ufficiali.<br>Una prospettiva tutta tua.</p><a href="https://www.leagueoflegends.com/it-it/news/tags/patch-notes/" target="_blank" rel="noopener">Note della patch <ArrowUpRight :size="15"/></a></div>
</aside>
<div class="main-shell">
<header class="topbar"><button class="mobile-menu icon-button" aria-label="Apri menu" @click="mobile=!mobile"><Menu/></button><div class="breadcrumb">League of Legends <ChevronRight :size="14"/><strong>{{nav.find(n=>n.id===tab)?.label}}</strong></div><div class="top-right"><span class="official-source">Riot Games Data</span><span class="patch-chip">PATCH {{patch.split('.').slice(0,2).join('.')}}</span></div></header>
<main>
<div class="page-heading"><div><div class="eyebrow">LEAGUE INTELLIGENCE</div><h1>{{tab==='overview'?'Ogni partita racconta qualcosa.':tab==='champions'?'Trova il tuo prossimo main.':tab==='items'?'La build comincia qui.':tab==='live'?'Dentro la Landa.':'Dati ufficiali. Nessuna magia.'}}</h1><p>{{tab==='overview'?'Il tuo profilo, i tuoi progressi, la tua prossima vittoria.':tab==='champions'?'Il roster completo. Statistiche, abilità e storie da scoprire.':tab==='items'?'Esplora gli oggetti della Landa degli evocatori.':tab==='live'?'Partita in corso, sfide e stato dei server.':'Le fonti, le possibilità e i limiti del tuo tracker.'}}</p></div><span class="season-stamp">{{new Date().getFullYear()}}<small>SUMMONER’S RIFT</small></span></div>
<form class="searchbar" @submit.prevent="search"><Search :size="21"/><input v-model="query" aria-label="Riot ID" placeholder="Cerca un giocatore · Nome#TAG" maxlength="81"/><label class="sr-only" for="region">Regione</label><select id="region" v-model="region"><option v-for="(label,key) in {euw1:'EU West',eun1:'EU Nordic & East',na1:'North America',kr:'Korea',br1:'Brazil',la1:'LAN',la2:'LAS',jp1:'Japan',oc1:'Oceania',tr1:'Türkiye',ru:'Russia',sg2:'Singapore',tw2:'Taiwan',vn2:'Vietnam'}" :value="key">{{label}}</option></select><button class="primary" :disabled="busy">{{busy?'Caricamento…':'Cerca giocatore'}}<Search :size="17"/></button></form>
<div v-if="error" class="notice error" role="alert">{{error}} <button @click="error=''" aria-label="Chiudi errore"><X :size="16"/></button></div>
<template v-if="tab==='overview'">
<div class="demo-note"><span class="mini-tag">{{demo?'DEMO':'PROFILO RIOT'}}</span><span>{{demo?'Stai esplorando un profilo dimostrativo. Cerca il tuo Riot ID per vedere le tue statistiche.':'Dati ufficiali Riot. Le statistiche recenti si riferiscono alle partite caricate.'}}</span><button v-if="!demo" @click="resetDemo">Apri demo</button><button v-else @click="go('sources')">{{config?.configured?'API collegata':'Collega API'}} <ArrowUpRight :size="14"/></button></div>
<section class="profile-hero"><img class="hero-art" src="https://ddragon.leagueoflegends.com/cdn/img/champion/splash/Ahri_0.jpg" alt="Illustrazione ufficiale di Ahri"/><div class="hero-shade"/><div class="profile-content"><div class="avatar-wrap"><img :src="`${cdn}/profileicon/${profile.summoner.profileIconId}.png`" alt="Icona evocatore"/><span>{{profile.summoner.summonerLevel}}</span></div><div><div class="profile-label">{{profile.region.toUpperCase()}} <span>•</span> {{demo?'PROFILO DIMOSTRATIVO':'PROFILO EVOCATORE'}}</div><h2>{{profile.account.gameName}}<span>#{{profile.account.tagLine}}</span></h2><div class="profile-sub"><span class="rank-dot"/> {{rank?`${rank.tier} ${rank.rank}`:'Non classificato'}}<span>·</span>Livello {{profile.summoner.summonerLevel}}</div></div></div><button class="hero-action" @click="demo?resetDemo():refreshProfile()" :disabled="busy"><RefreshCw :size="16"/>Aggiorna</button><span class="art-credit">AHRI / RIOT GAMES</span></section>
<div class="profile-tabs"><button class="selected">Panoramica</button><a href="#match-history">Storico partite <span>{{matches.length}}</span></a><a href="#champion-stats">Performance campioni</a><button @click="go('live')">Live & sfide</button><button class="export" @click="exportData"><Download :size="15"/>Esporta</button></div>
<div v-for="msg in profile.errors" class="notice error">{{msg}}</div>
<div class="dashboard-grid"><aside class="profile-side">
<section class="panel rank-panel"><div class="section-title"><h3>Ranked Solo / Duo</h3><Trophy :size="17"/></div><div class="rank-emblem"><Gem :size="58" :stroke-width="1.3"/></div><h2>{{rank?`${rank.tier} ${rank.rank}`:'Unranked'}}</h2><div class="lp">{{rank?`${rank.leaguePoints} LP`:'Nessun rank disponibile'}}</div><template v-if="rank"><div class="rank-progress"><i :style="{width:`${Math.min(100,rank.leaguePoints)}%`}"/></div><div class="rank-record"><span>{{rank.wins}} V <b>/</b> {{rank.losses}} S</span><strong>{{Math.round(rank.wins/(rank.wins+rank.losses)*100)}}% WR</strong></div></template><div v-if="profile.ranked?.find((r:any)=>r.queueType==='RANKED_FLEX_SR')" class="flex-rank"><span>Ranked Flex</span><strong>{{profile.ranked.find((r:any)=>r.queueType==='RANKED_FLEX_SR').tier}} {{profile.ranked.find((r:any)=>r.queueType==='RANKED_FLEX_SR').rank}}</strong></div></section>
<section class="panel" id="champion-stats"><div class="section-title"><h3>Campioni più giocati</h3><Swords :size="17"/></div><p class="section-note">Nelle {{stats.count}} partite filtrate</p><button v-for="c in championStats.slice(0,5)" :key="c.name" class="champion-stat" @click="openChampion(champions.find(x=>x.id===c.name)||{id:c.name,name:c.name})"><img :src="`${cdn}/champion/${c.name}.png`" :alt="c.name"/><div><strong>{{c.name}}</strong><small>{{((c.k+c.a)/Math.max(1,c.d)).toFixed(2)}} KDA · {{c.n}} partite</small></div><span :class="{'good':c.w/c.n>=.5}">{{Math.round(c.w/c.n*100)}}%<small>vittorie</small></span></button><p v-if="!championStats.length" class="muted">Carica le partite per vedere i campioni.</p></section>
<section class="panel"><div class="section-title"><h3>Maestria campioni</h3><Gem :size="17"/></div><div v-for="c in profile.mastery?.slice(0,3)" class="mastery-row"><img v-if="champion(c.championId)" :src="`${cdn}/champion/${champion(c.championId)?.id}.png`" :alt="champion(c.championId)?.name"/><div><strong>{{champion(c.championId)?.name||c.championId}}</strong><small>{{fmt(c.championPoints)}} punti</small></div><span>LV {{c.championLevel}}</span></div><p v-if="!profile.mastery?.length" class="muted">Nessuna maestria disponibile.</p></section>
</aside><div class="results">
<div class="stats-heading"><h3>La tua forma recente</h3><span>Ultime {{stats.count}} partite {{demo?'· demo':''}}</span></div><div class="stat-grid"><article class="stat-card win-card"><span>Win rate <Activity :size="16"/></span><strong>{{stats.wr}}<small>%</small></strong><div>{{stats.wins}} vittorie <span>· {{stats.count-stats.wins}} sconfitte</span></div><div class="win-strip"><i v-for="m in rows.slice(0,20)" :class="{loss:!m.me.win}" :title="m.me.win?'Vittoria':'Sconfitta'"/></div></article><article class="stat-card"><span>KDA medio <Crosshair :size="16"/></span><strong>{{stats.kda}}</strong><div>{{stats.kills}} <span>/ {{stats.deaths}} /</span> {{stats.assists}}</div><small class="muted">(Uccisioni + assist) / morti</small></article><article class="stat-card"><span>CS al minuto <Target :size="16"/></span><strong>{{stats.cs}}</strong><div>{{fmt(stats.damage)}} <span>danni medi</span></div><small class="muted">Visione media: {{stats.vision}}</small></article></div>
<section id="match-history" class="match-section"><div class="section-title history-title"><div><h3>Storico partite</h3><p class="section-note">I numeri dietro ogni GG.</p></div><SlidersHorizontal :size="18"/></div><div class="queue-filters"><button v-for="f in [{id:'all',label:'Tutte'},{id:'420',label:'Solo / Duo'},{id:'440',label:'Flex'},{id:'450',label:'ARAM'},{id:'400',label:'Normali'}]" :class="{selected:queue===f.id}" @click="queue=f.id">{{f.label}}</button><span>{{rows.length}} partite</span></div>
<div v-if="busy&&!rows.length" class="empty-state">Caricamento dello storico Riot…</div><div v-else-if="!rows.length" class="empty-state"><Swords/><h3>Nessuna partita in questa coda</h3><p>Prova un altro filtro o carica altre partite.</p></div>
<article v-for="m in rows" :key="m.metadata.matchId" :class="['match-card',m.me.win?'win':'loss']"><button class="match-main" @click="expanded=expanded===m.metadata.matchId?'':m.metadata.matchId" :aria-expanded="expanded===m.metadata.matchId"><div class="match-result"><strong>{{m.me.win?'Vittoria':'Sconfitta'}}</strong><span>{{queueName(m.info.queueId)}}</span><small>{{new Date(m.info.gameCreation).toLocaleDateString('it-IT',{day:'numeric',month:'short'})}} · {{duration(m.info.gameDuration)}}</small></div><div class="match-champion"><img class="champ-face" :src="`${cdn}/champion/${m.me.championName}.png`" :alt="m.me.championName"/><div class="spells"><img v-for="id in [m.me.summoner1Id,m.me.summoner2Id]" :src="`${cdn}/spell/${spell(id)?.image.full}`" :alt="spell(id)?.name||'Incantesimo'" :title="spell(id)?.name"/></div></div><div class="match-kda"><strong>{{m.me.kills}} <span>/ {{m.me.deaths}} /</span> {{m.me.assists}}</strong><small>{{((m.me.kills+m.me.assists)/Math.max(1,m.me.deaths)).toFixed(2)}} KDA</small><span class="position">{{m.me.teamPosition||'—'}}</span></div><div class="match-farm"><strong>{{m.me.totalMinionsKilled+m.me.neutralMinionsKilled}} CS</strong><small>{{((m.me.totalMinionsKilled+m.me.neutralMinionsKilled)/(m.info.gameDuration/60)).toFixed(1)}} / min</small><small>{{fmt(m.me.totalDamageDealtToChampions)}} danni</small></div><div class="match-items"><template v-for="id in [m.me.item0,m.me.item1,m.me.item2,m.me.item3,m.me.item4,m.me.item5,m.me.item6]"><img v-if="id" :src="`${cdn}/item/${id}.png`" :alt="itemName(id)" :title="itemName(id)"/><span v-else class="item-empty"/></template></div><ChevronDown :size="17" :class="{rotate:expanded===m.metadata.matchId}"/></button>
<div v-if="expanded===m.metadata.matchId" class="match-details"><div class="detail-heading"><span>{{m.metadata.matchId}} · Patch {{m.info.gameVersion.split('.').slice(0,2).join('.')}}</span><button @click="loadTimeline(m.metadata.matchId)">Apri timeline <Activity :size="14"/></button></div><div v-for="team in m.info.teams" class="team-table"><div class="team-title"><strong :class="team.win?'good':'bad'">{{team.win?'VITTORIA':'SCONFITTA'}} · TEAM {{team.teamId===100?'BLU':'ROSSO'}}</strong><span>{{team.objectives?.tower?.kills||0}} torri · {{team.objectives?.dragon?.kills||0}} draghi · {{team.objectives?.baron?.kills||0}} Baron</span></div><div class="scoreboard-head"><span>Giocatore</span><span>K / D / A</span><span>Danni</span><span>CS</span><span>Oggetti</span></div><div v-for="p in m.info.participants.filter((p:any)=>p.teamId===team.teamId)" :class="['scoreboard-row',{me:p.puuid===profile.account.puuid}]"><div><img :src="`${cdn}/champion/${p.championName}.png`" :alt="p.championName"/><span>{{p.riotIdGameName||p.championName}}<small>{{p.championName}}</small></span></div><span>{{p.kills}} / {{p.deaths}} / {{p.assists}}</span><span>{{fmt(p.totalDamageDealtToChampions)}}<i class="damage-bar" :style="{width:Math.max(5,p.totalDamageDealtToChampions/Math.max(...m.info.participants.map((a:any)=>a.totalDamageDealtToChampions))*100)+'%'}"/></span><span>{{p.totalMinionsKilled+p.neutralMinionsKilled}}</span><div class="table-items"><img v-for="id in [p.item0,p.item1,p.item2,p.item3,p.item4,p.item5].filter(Boolean)" :src="`${cdn}/item/${id}.png`" :alt="itemName(id)" :title="itemName(id)"/></div></div></div><div class="personal-details"><span><Eye :size="14"/> Visione {{m.me.visionScore}}</span><span>Oro {{fmt(m.me.goldEarned)}}</span><span v-if="rune(m.me.perks?.styles?.[0]?.selections?.[0]?.perk)"><img :src="`https://ddragon.leagueoflegends.com/cdn/img/${rune(m.me.perks.styles[0].selections[0].perk).icon}`" alt="Runa principale"/>{{rune(m.me.perks.styles[0].selections[0].perk).name}}</span></div></div></article>
<button v-if="hasMore" class="load-more" :disabled="busy" @click="loadMatches">{{busy?'Caricamento…':'Carica altre 10 partite'}}</button><p class="history-foot">{{demo?'Dati dimostrativi inventati; non rappresentano un giocatore reale.':'Statistiche sul campione caricato, non sull’intera carriera. Le partite personalizzate sono escluse.'}}</p>
</section></div></div>
</template>
<template v-else-if="tab==='champions'||tab==='items'"><div class="catalog-toolbar"><div class="catalog-search"><Search :size="18"/><input v-model="catalogQuery" :placeholder="tab==='champions'?'Cerca un campione…':'Cerca un oggetto…'" aria-label="Cerca nel catalogo"/></div><select v-model="role" aria-label="Filtra categoria"><option value="all">Tutte le categorie</option><option v-for="r in tab==='champions'?['Assassin','Fighter','Mage','Marksman','Support','Tank']:['Damage','SpellDamage','Armor','Health','Mana','AttackSpeed','CriticalStrike','Boots']" :value="r">{{r}}</option></select><span>{{tab==='champions'?filteredChampions.length:filteredItems.length}} risultati · {{patch}}</span></div><div v-if="tab==='champions'" class="champion-grid"><button v-for="c in filteredChampions" class="champion-tile" @click="openChampion(c)"><img :src="`https://ddragon.leagueoflegends.com/cdn/img/champion/loading/${c.id}_0.jpg`" :alt="c.name" loading="lazy"/><div><small>{{c.tags.join(' · ')}}</small><h2>{{c.name}}</h2><span>{{c.title}}</span></div><ArrowUpRight :size="20"/></button></div><div v-else class="item-grid"><button v-for="i in filteredItems" class="item-tile" @click="selected={...i,kind:'item'}"><img :src="`${cdn}/item/${i.image.full}`" :alt="i.name" loading="lazy"/><div><h3>{{i.name}}</h3><span>{{i.gold.total}} oro</span><p>{{strip(i.plaintext)||i.tags.slice(0,3).join(' · ')}}</p></div></button></div><div v-if="tab==='champions'?!filteredChampions.length:!filteredItems.length" class="empty-state">Nessun risultato. Prova a cambiare ricerca o categoria.</div></template>
<template v-else-if="tab==='live'"><div class="live-grid"><section class="panel"><Radio :size="30" class="good"/><h2>Partita in corso</h2><p>Controlla se {{profile.account.gameName}} è nella Landa e scopri le formazioni disponibili.</p><button class="primary" :disabled="extraBusy" @click="loadExtra('live')">Controlla partita</button></section><section class="panel"><Trophy :size="30" class="good"/><h2>Sfide del giocatore</h2><p>Punti, livello e progressi nelle sfide ufficiali di League of Legends.</p><button class="secondary" :disabled="extraBusy" @click="loadExtra('challenges')">Visualizza sfide</button></section><section class="panel"><Activity :size="30" class="good"/><h2>Stato del server</h2><p>Incidenti e manutenzioni nella regione {{profile.region.toUpperCase()}}.</p><button class="secondary" :disabled="extraBusy" @click="loadExtra('status')">Controlla server</button></section></div><p v-if="extraBusy" class="notice">Consultazione delle API Riot…</p><p v-if="extraError" class="notice error">{{extraError}}</p><section v-if="extra" class="panel extra-result"><template v-if="extra.kind==='live'"><h2>{{extra.data.active===false?'Nessuna partita in corso':'Partita in corso'}}</h2><p v-if="extra.data.active===false">Il giocatore non è in una partita osservabile tramite Spectator.</p><div v-else class="live-roster"><div v-for="p in extra.data.participants"><img :src="`${cdn}/champion/${champion(p.championId)?.id}.png`" :alt="champion(p.championId)?.name"/><strong>{{p.riotId||champion(p.championId)?.name}}</strong><span>Team {{p.teamId}}</span></div></div></template><template v-if="extra.kind==='challenges'"><h2>{{extra.data.totalPoints?.level}} · {{fmt(extra.data.totalPoints?.current)}} punti</h2><div class="challenge-grid"><div v-for="(v,k) in extra.data.categoryPoints"><h3>{{k}}</h3><p>{{(v as any).level}} · {{fmt((v as any).current)}} punti</p></div></div><details><summary>Tutti i progressi (JSON)</summary><pre>{{JSON.stringify(extra.data.challenges,null,2)}}</pre></details></template><template v-if="extra.kind==='status'"><h2>{{extra.data.name}}</h2><p v-if="!extra.data.incidents?.length&&!extra.data.maintenances?.length" class="good">Nessun incidente o manutenzione segnalati.</p><article v-for="s in [...(extra.data.incidents||[]),...(extra.data.maintenances||[])]"><h3>{{s.titles?.find((t:any)=>t.locale==='it_IT')?.content||s.titles?.[0]?.content}}</h3><p v-for="u in s.updates">{{u.translations?.find((t:any)=>t.locale==='it_IT')?.content||u.translations?.[0]?.content}}</p></article></template></section></template>
<template v-else><div class="sources-grid"><section class="panel"><span :class="['status-pill',config?.configured?'connected':'']">{{config?.configured?'Chiave server configurata':'Chiave Riot da configurare'}}</span><h2>Collega il tuo mondo di League.</h2><p>Campioni, oggetti e immagini funzionano già con Data Dragon. Per i profili reali serve una chiave personale del Riot Developer Portal.</p><ol><li>Accedi al portale Riot e genera una API key.</li><li>Imposta <code>NUXT_RIOT_API_KEY</code> nell’ambiente del server.</li><li>Riavvia o ripubblica e cerca <strong>Nome#TAG</strong> con la regione corretta.</li></ol><p>La chiave resta sul server. Le development key scadono dopo 24 ore; per un servizio pubblico serve registrare il prodotto e ottenere l’accesso appropriato.</p><a class="primary inline-flex" href="https://developer.riotgames.com/" target="_blank" rel="noopener">Riot Developer Portal <ExternalLink :size="16"/></a></section><section class="panel"><h2>Cosa puoi sapere</h2><div class="api-row" v-for="a in [['ACCOUNT-V1 · SUMMONER-V4','Riot ID, PUUID, livello e icona'],['LEAGUE-V4','Rank, LP, vittorie e sconfitte per coda'],['MATCH-V5','Partite, partecipanti, build, rune, obiettivi e timeline'],['CHAMPION-MASTERY-V4','Livelli e punti maestria'],['SPECTATOR-V5 · CHALLENGES-V1','Partita in corso e progressi delle sfide'],['DATA DRAGON','Campioni, statistiche base, abilità, skin, oggetti e icone']]" :key="a[0]"><strong>{{a[0]}}</strong><span>{{a[1]}}</span></div></section><section class="panel"><h2>Come leggere le statistiche</h2><p>Win rate, KDA, CS/min e danni vengono calcolati sul campione caricato e cambiano con il filtro della coda. Rank e maestria provengono direttamente da Riot.</p><p>Non vengono inventati MMR, rank storici o statistiche globali. L’API non espone email, password, messaggi privati o un inventario completo delle skin possedute.</p><p>I dettagli delle partite usano le icone della patch Data Dragon mostrata; gli oggetti storici potrebbero essere stati modificati.</p></section><section class="panel"><h2>Fonti & aggiornamenti</h2><p>Catalogo ufficiale {{patch}}, sincronizzato il {{new Date(version?.updated).toLocaleDateString('it-IT')}}. Le nuove patch possono arrivare su Data Dragon con un ritardo rispetto al client.</p><p>Cache temporanea lato server, paginazione a 10 partite e gestione degli errori Riot. Il progetto include un comando per aggiornare il catalogo.</p><a href="https://developer.riotgames.com/docs/lol" target="_blank" rel="noopener">Documentazione League of Legends <ExternalLink :size="14"/></a><a href="https://developer.riotgames.com/apis" target="_blank" rel="noopener">Riferimento delle API <ExternalLink :size="14"/></a></section></div></template>
<footer><a class="footer-brand" href="#" @click.prevent="go('overview')">riftrecap<span> / </span>GG, go next.</a><p>Rift Recap is not endorsed by Riot Games and does not reflect the views or opinions of Riot Games or anyone officially involved in producing or managing Riot Games properties. Riot Games and all associated properties are trademarks or registered trademarks of Riot Games, Inc.</p></footer>
</main>
</div>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="detail-modal" role="dialog" aria-modal="true" :aria-label="selected.name" tabindex="-1"><button class="modal-close icon-button" autofocus @click="selected=null" aria-label="Chiudi dettagli"><X/></button><template v-if="selected.kind==='champion'"><img class="modal-splash" :src="`https://ddragon.leagueoflegends.com/cdn/img/champion/splash/${selected.id}_0.jpg`" :alt="selected.name"/><div class="modal-body"><span class="eyebrow">{{selected.tags?.join(' / ')}}</span><h2>{{selected.name}}</h2><p class="muted">{{selected.title}}</p><p v-if="detailBusy">Caricamento delle abilità…</p><p v-if="detailError" class="bad">{{detailError}}</p><template v-if="detail"><p>{{strip(detail.lore)}}</p><div class="base-stats"><span v-for="(label,key) in {hp:'Salute',attackdamage:'Attacco',armor:'Armatura',movespeed:'Velocità'}">{{label}}<strong>{{detail.stats[key]}}</strong></span></div><h3>Abilità</h3><div class="ability"><img :src="`${cdn}/passive/${detail.passive.image.full}`" alt="Passiva"/><div><h4>{{detail.passive.name}} <small>PASSIVA</small></h4><p>{{strip(detail.passive.description)}}</p></div></div><div v-for="(s,i) in detail.spells" class="ability"><img :src="`${cdn}/spell/${s.image.full}`" :alt="s.name"/><div><h4>{{s.name}} <small>{{['Q','W','E','R'][Number(i)]}}</small></h4><p>{{strip(s.description)}}</p><small>Ricarica {{s.cooldownBurn}} · Costo {{s.costBurn}}</small></div></div><h3>Skin · {{detail.skins.length}}</h3><div class="skin-list"><span v-for="s in detail.skins">{{s.name==='default'?'Originale':s.name}}</span></div></template></div></template><div v-else-if="selected.kind==='item'" class="modal-body item-detail"><img :src="`${cdn}/item/${selected.image.full}`" :alt="selected.name"/><span class="eyebrow">OGGETTO · {{patch}}</span><h2>{{selected.name}}</h2><p class="gold">{{selected.gold.total}} oro · Vendita {{selected.gold.sell}} oro</p><p>{{strip(selected.description)}}</p><h3 v-if="selected.from?.length">Componenti</h3><div class="build-path"><button v-for="id in selected.from" @click="selected={...itemData.data[id],id,kind:'item'}"><img :src="`${cdn}/item/${id}.png`" :alt="itemName(id)"/><span>{{itemName(id)}}</span></button></div><h3 v-if="selected.into?.length">Si trasforma in</h3><div class="build-path"><button v-for="id in selected.into" @click="selected={...itemData.data[id],id,kind:'item'}"><img :src="`${cdn}/item/${id}.png`" :alt="itemName(id)"/><span>{{itemName(id)}}</span></button></div></div><div v-else class="modal-body"><h2>{{selected.name}}</h2><p v-if="detailBusy">Caricamento…</p><p v-if="detailError" class="notice">{{detailError}}</p><template v-if="timeline"><p>Eventi ufficiali per minuto: uccisioni, obiettivi e acquisti.</p><details v-for="f in timeline.info.frames"><summary>{{duration(f.timestamp/1000)}} · {{f.events.length}} eventi</summary><div v-for="e in f.events" class="timeline-event"><strong>{{e.type}}</strong><span>{{e.monsterType||e.buildingType||(e.itemId?itemName(e.itemId):'')}}</span><small v-if="e.killerId">Partecipante {{e.killerId}} → {{e.victimId||'obiettivo'}}</small></div></details></template></div></section></div>
</div>
</template>
